import { Entity, PrimaryKey, Property, Unique } from '@mikro-orm/decorators/legacy';
import type { User } from '../../modules/users/user.js';

export const USERS_EMAIL_UNIQUE = 'users_email_unique';

/** A user without their roles; those are `UserRoleEntity` rows. */
@Entity({ tableName: 'users' })
@Unique({ name: USERS_EMAIL_UNIQUE, properties: ['email'] })
export class UserEntity implements Omit<User, 'roles'> {
  /** A UUIDv7 generated by the repository, so ids sort by creation time. */
  @PrimaryKey({ type: 'uuid' })
  id!: string;

  @Property({ type: 'text' })
  email!: string;

  @Property({ type: 'text' })
  passwordHash!: string;

  @Property({ type: 'text' })
  name!: string;

  @Property({ type: 'datetime', nullable: true })
  emailVerifiedAt!: Date | null;

  @Property({ type: 'datetime', defaultRaw: 'now()' })
  createdAt!: Date;

  /** Set to the current time by every update. */
  @Property({ type: 'datetime', defaultRaw: 'now()' })
  updatedAt!: Date;
}
